import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Webcam from "react-webcam";
import {
  getAuth,
  RecaptchaVerifier,
  signInWithPhoneNumber,
} from "firebase/auth";
import axios from "axios";
import "./Login.css";
import app from "../../firebase";

const auth = getAuth(app);

const Login = () => {
  const navigate = useNavigate();
  const [name, setName] = useState("");
  const [aadhaarNumber, setAadhaarNumber] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [confirmationResult, setConfirmationResult] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showWebcam, setShowWebcam] = useState(false);
  const [verificationSuccess, setVerificationSuccess] = useState(false);
  const [captureSuccess, setCaptureSuccess] = useState(false);
  const [fingerprintImage, setFingerprintImage] = useState(null);
  const [fingerprintTemplate, setFingerprintTemplate] = useState(null);
  const [capturingFingerprint, setCapturingFingerprint] = useState(false);
  const [fingerprintCaptured, setFingerprintCaptured] = useState(false);
  const [faceCaptured, setFaceCaptured] = useState(false);
  const webcamRef = React.useRef(null);

  React.useEffect(() => {
    return () => {
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    };
  }, []);

  const reCaptchverify = () => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(
        auth,
        "recaptcha-container",
        {
          size: "normal",
          callback: (response) => {
            console.log("reCAPTCHA solved", response);
          },
          "expired-callback": () => {
            console.log("reCAPTCHA expired");
            window.recaptchaVerifier.render().then((widgetId) => {
              window.recaptchaWidgetId = widgetId;
            });
          },
        }
      );
    }
    return window.recaptchaVerifier;
  };

  const verifyCode = () => {
    if (!confirmationResult) {
      setError("No confirmation result available");
      return Promise.reject("No confirmation result");
    }
    return confirmationResult.confirm(otp);
  };

  const validateInputs = () => {
    if (!name.trim()) {
      setError("Please enter your name as per Aadhaar");
      return false;
    }
    if (!aadhaarNumber || aadhaarNumber.length !== 12) {
      setError("Please enter a valid 12-digit Aadhaar number");
      return false;
    }
    if (!phoneNumber || phoneNumber.length !== 10) {
      setError("Please enter a valid 10-digit phone number");
      return false;
    }
    return true;
  };

  const sendOTP = async () => {
    setError("");
    if (!validateInputs()) return;

    setLoading(true);
    try {
      const verifier = reCaptchverify();
      const formattedPhone = `+91${phoneNumber}`;

      await verifier.render();
      const result = await signInWithPhoneNumber(
        auth,
        formattedPhone,
        verifier
      );

      setConfirmationResult(result);
      setOtpSent(true);
      setError("");
      console.log("OTP sent successfully");
    } catch (error) {
      console.error("OTP sending error:", error);
      setError(`Failed to send OTP: ${error.message}`);
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    } finally {
      setLoading(false);
    }
  };

  const verifyOTP = async () => {
    setError("");
    if (!otp || otp.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    setLoading(true);
    try {
      await verifyCode();
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }

      const recaptchaContainer = document.getElementById("recaptcha-container");
      if (recaptchaContainer) {
        recaptchaContainer.innerHTML = "";
      }

      setVerificationSuccess(true);
      setShowWebcam(true);
      setError("");
    } catch (error) {
      setError("Invalid OTP. Please try again.");
      console.error("OTP verification error:", error);
    } finally {
      setLoading(false);
    }
  };

  // Capture fingerprint using PB1000 scanner
  const captureFingerprint = async () => {
    setCapturingFingerprint(true);
    setError("");

    try {
      const response = await axios.post(
        "http://localhost:5000/api/capture-fingerprint"
      );

      if (response.data.success) {
        const { image, template } = response.data.data;
        setFingerprintImage(image);
        setFingerprintTemplate(template);
        setFingerprintCaptured(true);

        console.log("✅ Fingerprint captured successfully");

        // Auto-submit after fingerprint capture if face is already captured
        if (faceCaptured) {
          await submitAllData();
        }
      } else {
        throw new Error(
          response.data.message || "Failed to capture fingerprint"
        );
      }
    } catch (error) {
      console.error("Fingerprint capture error:", error);
      setError(`Fingerprint capture failed: ${error.message}`);
    } finally {
      setCapturingFingerprint(false);
    }
  };

  const captureFaceImage = () => {
    const imageSrc = webcamRef.current.getScreenshot();
    if (!imageSrc) {
      setError("Failed to capture face image. Please try again.");
      return;
    }

    // Convert base64 to blob
    fetch(imageSrc)
      .then((res) => res.blob())
      .then((blob) => {
        const file = new File([blob], `face_${Date.now()}.png`, {
          type: "image/png",
        });
        setFaceCaptured(true);
        setShowWebcam(false); // Hide webcam but keep biometric section visible

        // Store face image for later submission
        localStorage.setItem("faceImage", URL.createObjectURL(blob));
        localStorage.setItem(
          "faceImageFile",
          JSON.stringify({
            name: file.name,
            type: file.type,
            size: file.size,
          })
        );

        console.log("✅ Face captured successfully");
      })
      .catch((error) => {
        console.error("Error capturing face image:", error);
        setError("Failed to process face image. Please try again.");
      });
  };

  const handleFingerprintUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFingerprintImage(file);
      setFingerprintCaptured(true);
      setFingerprintTemplate(`uploaded_template_${Date.now()}`);
      console.log("✅ Fingerprint image uploaded");
    }
  };

  const submitAllData = async () => {
    setLoading(true);
    try {
      const formData = new FormData();
      formData.append("name", name);
      formData.append("aadhaarNumber", aadhaarNumber);
      formData.append("phoneNumber", phoneNumber);
      formData.append("otp", otp);

      // Add face image if captured
      if (faceCaptured) {
        const imageSrc = webcamRef.current?.getScreenshot();
        if (imageSrc) {
          const response = await fetch(imageSrc);
          const blob = await response.blob();
          const faceFile = new File([blob], `face_${Date.now()}.png`, {
            type: "image/png",
          });
          formData.append("faceImage", faceFile);
        }
      }

      // Add fingerprint data if available
      if (fingerprintImage && fingerprintImage instanceof File) {
        formData.append("fingerprintImage", fingerprintImage);
      }

      if (fingerprintTemplate && fingerprintTemplate.trim() !== "") {
        formData.append("fingerprintTemplate", fingerprintTemplate);
      }

      console.log("📤 Submitting all verification data...");

      const response = await axios.post(
        "http://localhost:5000/api/verify-user",
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
          timeout: 30000,
        }
      );

      if (response.data.success) {
        setCaptureSuccess(true);
        setError("");
        console.log("✅ All verification data saved successfully");

        setTimeout(() => {
          resetForm();
          alert(
            "✅ Verification completed successfully! Data saved to database."
          );
        }, 2000);
      }
    } catch (error) {
      console.error("❌ Submission error:", error);

      if (error.response?.data?.message?.includes("already voted")) {
        setError(`❌ ${error.response.data.message}`);
      } else if (error.response?.data?.message) {
        setError(`Submission failed: ${error.response.data.message}`);
      } else if (error.code === "ECONNREFUSED") {
        setError(
          "❌ Cannot connect to server. Please make sure the backend is running."
        );
      } else {
        setError("Failed to submit verification data. Please try again.");
      }
      setCaptureSuccess(false);
    } finally {
      setLoading(false);
    }
  };

  const handleManualSubmit = async () => {
    if (!faceCaptured) {
      setError("Please capture your face image first.");
      return;
    }

    if (!fingerprintCaptured) {
      setError("Please capture or upload your fingerprint.");
      return;
    }

    await submitAllData();
  };

  const resetForm = () => {
    setName("");
    setAadhaarNumber("");
    setPhoneNumber("");
    setOtp("");
    setOtpSent(false);
    setVerificationSuccess(false);
    setCaptureSuccess(false);
    setFingerprintImage(null);
    setFingerprintTemplate(null);
    setFingerprintCaptured(false);
    setFaceCaptured(false);
    setError("");
    setShowWebcam(false);
    localStorage.removeItem("faceImage");
    localStorage.removeItem("faceImageFile");
  };

  const handleAadhaarChange = (e) => {
    setAadhaarNumber(e.target.value.replace(/\D/g, "").slice(0, 12));
  };

  const handlePhoneChange = (e) => {
    setPhoneNumber(e.target.value.replace(/\D/g, "").slice(0, 10));
  };

  const handleOtpChange = (e) => {
    setOtp(e.target.value.replace(/\D/g, "").slice(0, 6));
  };

  const goToAdminLogin = () => {
    navigate("/admin-login");
  };

  const testBackendConnection = async () => {
    try {
      setError("");
      const response = await axios.get("http://localhost:5000/api/health");
      if (response.data.success) {
        alert(
          `✅ Backend is healthy!\nDatabase: ${response.data.database}\nFingerprint Column: ${response.data.fingerprint_template_column}`
        );
      }
    } catch (error) {
      alert(
        "❌ Backend connection failed. Please make sure the server is running on port 5000."
      );
    }
  };

  React.useEffect(() => {
    if (captureSuccess) {
      setError("");
    }
  }, [captureSuccess]);

  return (
    <div className="login-background">
      <div className="login-container">
        <div className="user-login">
          <h2>🗳️ E-Voting User Verification</h2>

          <div style={{ textAlign: "center", marginBottom: "15px" }}>
            <button
              onClick={testBackendConnection}
              className="test-connection-btn"
            >
              🔍 Test Backend Connection
            </button>
          </div>

          <div id="recaptcha-container"></div>

          {error && !captureSuccess && (
            <div className="error-message">{error}</div>
          )}

          {verificationSuccess && !captureSuccess && (
            <div className="success-message">
              ✅ OTP Verified! Please complete biometric verification.
            </div>
          )}

          {captureSuccess && (
            <div className="success-message">
              ✅ Verification Complete! Data saved to database.
            </div>
          )}

          {!verificationSuccess ? (
            <>
              <input
                type="text"
                placeholder="Full Name as per Aadhaar"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="form-input"
                disabled={loading}
              />

              <input
                type="text"
                placeholder="Aadhaar Number (12 digits)"
                value={aadhaarNumber}
                onChange={handleAadhaarChange}
                className="form-input"
                maxLength="12"
                disabled={loading}
              />

              <input
                type="text"
                placeholder="Phone Number (10 digits)"
                value={phoneNumber}
                onChange={handlePhoneChange}
                className="form-input"
                maxLength="10"
                disabled={loading}
              />

              {!otpSent ? (
                <button
                  onClick={sendOTP}
                  className="otp-button"
                  disabled={loading}
                >
                  {loading ? "Sending OTP..." : "📱 Send OTP"}
                </button>
              ) : (
                <>
                  <input
                    type="text"
                    placeholder="Enter OTP (6 digits)"
                    value={otp}
                    onChange={handleOtpChange}
                    className="form-input"
                    maxLength="6"
                    disabled={loading}
                  />
                  <div className="button-group">
                    <button
                      onClick={verifyOTP}
                      className="verify-button"
                      disabled={loading}
                    >
                      {loading ? "Verifying..." : "✅ Verify OTP"}
                    </button>
                    <button
                      onClick={sendOTP}
                      className="resend-button"
                      disabled={loading}
                    >
                      🔄 Resend OTP
                    </button>
                  </div>
                </>
              )}
            </>
          ) : (
            /* BIOMETRIC SECTION - Always visible after OTP verification */
            <div className="biometric-section">
              {/* Face Capture Section */}
              <div className="webcam-section">
                <h3>📷 Face Verification {faceCaptured && "✅"}</h3>

                {showWebcam ? (
                  <>
                    <Webcam
                      audio={false}
                      ref={webcamRef}
                      screenshotFormat="image/png"
                      width={320}
                      height={240}
                      style={{ borderRadius: "8px", border: "2px solid #ddd" }}
                    />
                    <br />
                    <div className="button-group">
                      <button
                        onClick={captureFaceImage}
                        className="capture-button"
                        disabled={loading}
                      >
                        📸 Capture Face
                      </button>
                      <button
                        onClick={() => setShowWebcam(false)}
                        className="resend-button"
                      >
                        ❌ Cancel
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="webcam-controls">
                    {!faceCaptured ? (
                      <button
                        onClick={() => setShowWebcam(true)}
                        className="capture-button"
                      >
                        📷 Start Face Capture
                      </button>
                    ) : (
                      <div className="success-status">
                        <span style={{ color: "white", fontWeight: "bold" }}>
                          ✅ Face Captured Successfully
                        </span>
                        <button
                          onClick={() => setShowWebcam(true)}
                          className="resend-button"
                          style={{ marginTop: "10px" }}
                        >
                          🔄 Retake Face
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Fingerprint Section - Always visible after OTP verification */}
              <div className="fingerprint-section">
                <h4>
                  👆 Fingerprint Verification {fingerprintCaptured && "✅"}
                </h4>

                <div style={{ marginBottom: "15px" }}>
                  <button
                    onClick={captureFingerprint}
                    className="capture-button"
                    disabled={capturingFingerprint || loading}
                    style={{ marginBottom: "10px", width: "100%" }}
                  >
                    {capturingFingerprint
                      ? "🔄 Capturing Fingerprint..."
                      : "🔒 Capture Fingerprint (PB1000)"}
                  </button>

                  {fingerprintCaptured && (
                    <div className="fingerprint-status fingerprint-success">
                      ✅ Fingerprint Captured Successfully
                    </div>
                  )}
                </div>

                <div style={{ textAlign: "center", margin: "10px 0" }}>
                  <span style={{ color: "white" }}>OR</span>
                </div>

                <div>
                  <h5 style={{ color: "white", marginBottom: "10px" }}>
                    Upload Fingerprint Image
                  </h5>
                  <input
                    type="file"
                    accept="image/*,.bmp"
                    onChange={handleFingerprintUpload}
                    className="form-input"
                    disabled={loading}
                  />
                </div>

                {/* Submit Button - Only show when both biometrics are captured */}
                {faceCaptured && fingerprintCaptured && (
                  <div style={{ marginTop: "20px", textAlign: "center" }}>
                    <button
                      onClick={handleManualSubmit}
                      className="verify-button"
                      disabled={loading}
                      style={{
                        width: "100%",
                        padding: "15px",
                        fontSize: "18px",
                      }}
                    >
                      {loading
                        ? "🔄 Submitting..."
                        : "🚀 Complete Verification"}
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}

          <div style={{ marginTop: "20px", textAlign: "center" }}>
            <button onClick={goToAdminLogin} className="admin-btn">
              👨‍💼 Admin Login
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
